// src/ui/launcher.ts
import { spawn as spawn4 } from "node:child_process";
var UI_PAGES = ["profiles", "ai-setup", "demos", "site", "demo", "axl", "monitoring", "data"];
function openInCursor(dir2) {
  if ((process.env.GCTK_BROWSER ?? "").toLowerCase() === "none") return Promise.resolve(false);
  const [cmd, args] = process.platform === "darwin" ? ["open", ["-a", "Cursor", dir2]] : ["cursor", [dir2]];
  return new Promise((resolve2) => {
    const child = spawn4(cmd, args, { stdio: "ignore", detached: true, shell: process.platform === "win32" });
    child.on("error", () => resolve2(false));
    child.on("exit", (code) => resolve2(code === 0));
  });
}
function openBrowser(url2) {
  if ((process.env.GCTK_BROWSER ?? "").toLowerCase() === "none") return Promise.resolve(false);
  const [cmd, args] = process.platform === "darwin" ? ["open", [url2]] : process.platform === "win32" ? ["cmd", ["/c", "start", "", url2]] : ["xdg-open", [url2]];
  return new Promise((resolve2) => {
    const child = spawn4(cmd, args, { stdio: "ignore", detached: true });
    child.on("error", () => resolve2(false));
    child.on("spawn", () => {
      child.unref();
      resolve2(true);
    });
  });
}

