var INSTRUCTIONS = `Genesys Cloud Toolkit: a local web UI that makes the user's AI setup and Genesys Cloud demos
transparent. gc_ui opens it (orgs, AI setup, projects and AXL workshops, demo website, Demo ready,
monitoring); gc_ai_setup tells which MCP servers Cursor loads and which org each server works on; gc_axl tells which org and Genesys tools a project folder or AXL workshop has. Secrets are never shown. Org credentials are entered
on the Orgs page of the UI, never in the chat.`;
async function guarded(fn) {
  try {
    return { content: [{ type: "text", text: await fn() }] };
  } catch (err) {
    return { content: [{ type: "text", text: formatError(err) }], isError: true };
  }
}
function createServer() {
  const server = new McpServer({ name: "gctk", version: VERSION4 }, { instructions: INSTRUCTIONS });
  server.registerTool(
    "gc_ui",
    {
      title: "Open the gctk UI",
      description: "Open the local gctk web UI in the user's browser: profiles (Orgs: add orgs and their OAuth credentials, which go straight into the OS keychain), ai-setup (Cursor setup: the MCP servers Cursor loads, the org each works on, where its credentials are; fixes such as moving a plain-text secret into the keychain), demos (deploy a whole demo into an org with one button, start what it needs on this computer), site (a demo customer website with the org's Messenger), demo (Demo ready: agent home-screen data, refresh, clean up), axl (Projects: demo folders with their own org and Genesys tools, and AXL workshops) and monitoring (object counts against the org's limits). Use it when the user wants to connect an org, check or fix their AI setup, or prepare a demo. The UI's session link goes to the browser only; you never see it.",
      inputSchema: { page: external_exports.enum(UI_PAGES).default("profiles") },
      annotations: { readOnlyHint: true, destructiveHint: false, openWorldHint: false }
    },
    ({ page }) => guarded(async () => {
      const url2 = await ensureSharedUi();
      return await openBrowser(`${url2}&view=${page}`) ? `Opened the gctk UI (${page}) in the user's browser. It keeps running in the background, also after this session, and all sessions share it.` : "Could not open a browser on this machine. Ask the user to run `npx -y github:diebergziege/gc-toolkit ui` in a terminal.";
    })
  );
  server.registerTool(
    "gc_axl",
    {
      title: "Project and AXL workshop settings",
      description: "Project folders and AXL (AI Agent eXperience Lab) workshops the user manages on the Projects page of the gctk UI. Pass folder = your Cursor workspace to get that folder's project: the Genesys Cloud org its tools work on and which Genesys tools gctk starts there; for an AXL workshop also the folder's sessions (axl-sessions/), whether Cursor started the ava-harness, and the sessions' artifacts. Without folder: the list. Call it before you build in a folder and tell the user which org you are about to change. Read-only.",
      inputSchema: { folder: external_exports.string().max(1e3).optional().describe("absolute path of the Cursor workspace the lab runs in") },
      annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false }
    },
    ({ folder }) => guarded(async () => formatAxlStatus(axlStatus(), folder))
  );
  server.registerTool(
    "gc_ai_setup",
    {
      title: "Cursor's MCP servers",
      description: "The MCP servers Cursor loads: ~/.cursor/mcp.json (every folder), Cursor plugins, and the .cursor/mcp.json of the folders Cursor knows. For each server: file, command, how it gets its Genesys credentials (plain text in the file, keychain, gctk orgs, a gctk project) and which gctk org its OAuth client belongs to; problems such as plain-text secrets, the same secret in several files and missing commands. Secrets are always masked. Use it when the user asks which MCP server works on which org, where credentials are, or why a server does not start. Read-only: fixes (moving a secret to the keychain, another org, removing an entry) are pressed by the user on the Cursor setup page (gc_ui page ai-setup); a folder's own org and tools are set on the Projects page (gc_ui page axl).",
      inputSchema: {},
      annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false }
    },
    () => guarded(async () => formatAiSetup(scanAiSetup()))
  );
  return server;
}
async function runMcpServer() {
  await createServer().connect(new StdioServerTransport());
}

// src/cli/prompt.ts
import readline from "node:readline";
import { Writable } from "node:stream";
async function ask(question, opts = {}) {
  if (!process.stdin.isTTY) {
    throw new Error("Interactive input needs a terminal. Use --from-env for non-interactive setups.");
  }
  let muted = false;
  const output2 = new Writable({
    write(chunk, _enc, cb) {
      if (!muted) process.stdout.write(chunk);
      cb();
    }
  });
  const rl = readline.createInterface({ input: process.stdin, output: output2, terminal: true });
  try {
    return await new Promise((resolve2) => {
      rl.question(question, (answer2) => resolve2(answer2.trim()));
      muted = Boolean(opts.hidden);
    });
  } finally {
    rl.close();
    if (opts.hidden) process.stdout.write("\n");
  }
}

// src/cli/index.ts
var VERSION5 = true ? "0.28.0" : "dev";
var program2 = new Command().name("gctk").description("Genesys Cloud Toolkit: a local UI that makes your AI setup and Genesys Cloud demos transparent").version(VERSION5).option("-p, --profile <name>", "profile to use (default: GCTK_PROFILE or the active profile)");
var profile = program2.command("profile").description("manage org connections (profiles)");
profile.command("add <name>").description("create a profile and store its OAuth client credentials in the keychain").requiredOption("-r, --region <region>", "domain (mypurecloud.de) or region key (eu-central-1)").addOption(new Option("-t, --tier <tier>", "environment tier").choices([...TIERS]).makeOptionMandatory()).option("-d, --description <text>", "free text, e.g. customer or purpose").option("--env-credentials", "read credentials from GCTK_CLIENT_ID / GCTK_CLIENT_SECRET instead of the keychain (CI)").option("--no-login", "do not ask for credentials now").action(async (name, o) => {
  assertProfileName(name);
  if (listProfiles().includes(name)) throw new GctkError("PROFILE_EXISTS", `Profile "${name}" already exists.`);
  const p = {
    name,
    region: resolveRegion(o.region),
    tier: o.tier,
    description: o.description,
    credentials: o.envCredentials ? "env" : "keychain"
  };
  saveProfile(p);
  console.log(`Created profile "${name}" (${p.tier}, ${p.region})`);
  console.log(`  ${paths.profile(name)}`);
  if (!getActiveProfileName()) {
    setActiveProfileName(name);
    console.log("  set as active profile");
  }
  if (p.credentials === "keychain" && o.login) await login(name, {});
});
profile.command("list").description("list profiles").action(() => {
  const active = getActiveProfileName();
  const names = listProfiles();
  if (!names.length) return console.log("No profiles yet. Create one: gctk profile add <name> --region <region> --tier <tier>");
  for (const n of names) {
    try {
      const p = loadProfile(n);
      const creds = hasStoredCredentials(p) ? "credentials ok" : "NO CREDENTIALS";
      console.log(`${n === active ? "*" : " "} ${n.padEnd(20)} ${p.tier.padEnd(10)} ${p.region.padEnd(22)} ${creds}`);
    } catch (err) {
      console.log(`  ${n.padEnd(20)} INVALID: ${formatError(err)}`);
    }
  }
});
profile.command("show [name]").description("show a profile").action((name) => {
  const p = loadProfile(name ?? resolveProfileName(program2.opts().profile));
  console.log(toJson({ ...p, credentialsStored: hasStoredCredentials(p), file: paths.profile(p.name) }));
});
profile.command("use <name>").description("set the active profile (default for CLI and new MCP sessions)").action((name) => {
  setActiveProfileName(name);
  const p = loadProfile(name);
  console.log(`Active profile: ${name} (${p.tier}, ${p.region})`);
});
profile.command("remove <name>").description("delete a profile and its stored credentials").action((name) => {
  const p = loadProfile(name);
  if (p.credentials === "keychain") deleteCredentials(name);
  removeProfile(name);
  console.log(`Removed profile "${name}" and its keychain entry.`);
});
async function login(name, o) {
  const p = loadProfile(name);
  if (p.credentials === "env") {
    throw new GctkError("ENV_PROFILE", `Profile "${name}" reads credentials from the environment; nothing to store.`);
  }
  let clientId;
  let clientSecret;
  if (o.fromEnv) {
    clientId = process.env.GCTK_CLIENT_ID;
    clientSecret = process.env.GCTK_CLIENT_SECRET;
    if (!clientId || !clientSecret) throw new GctkError("MISSING_CREDENTIALS", "GCTK_CLIENT_ID / GCTK_CLIENT_SECRET are not set.");
  } else {
    console.log(`OAuth client (Client Credentials grant) for ${p.region}. Input is stored in the ${keychainName()}.`);
    clientId = await ask("Client ID: ");
    clientSecret = await ask("Client secret (hidden): ", { hidden: true });
  }
  if (!clientId || !clientSecret) throw new GctkError("MISSING_CREDENTIALS", "Client ID and secret are required.");
  storeCredentials(p, { clientId, clientSecret });
  console.log(`Stored credentials for "${name}". Verifying...`);
  const org = (await new GenesysClient(p, { source: "cli" }).get("/api/v2/organizations/me")).body;
  console.log(`OK: org ${org.name ?? org.id}`);
}
program2.command("login [profile]").description("store or replace OAuth client credentials for a profile in the OS keychain").option("--from-env", "take them from GCTK_CLIENT_ID / GCTK_CLIENT_SECRET").action((name, o) => login(name ?? resolveProfileName(program2.opts().profile), o));
program2.command("logout [profile]").description("delete stored credentials for a profile").action((name) => {
  const n = name ?? resolveProfileName(program2.opts().profile);
  deleteCredentials(n);
  console.log(`Removed credentials for "${n}" from the ${keychainName()}.`);
});
program2.command("ui [page]").description(`open the local web UI (runs in the background, shared by all sessions); page: ${UI_PAGES.join(", ")}`).option("--port <n>", "port for --foreground (default: random free port)").option("--no-open", "do not open the browser").option("--foreground", "run in this terminal instead of the background (stop with Ctrl+C)").option("--stop", "stop the background UI").option("--daemon", "internal: run as the background UI process").action(async (page, o) => {
  if (o.daemon) return runUiDaemon({ port: o.port ? Number(o.port) : void 0 });
  if (page && !UI_PAGES.includes(page)) throw new GctkError("INVALID_INPUT", `Unknown page "${page}". Pages: ${UI_PAGES.join(", ")}.`);
  const target = (url3) => page ? `${url3}&view=${page}` : url3;
  if (o.stop) return console.log(stopRunningUi() ? "Stopped the gctk UI." : "No gctk UI was running.");
  if (o.foreground) {
    const ui = await startUi({ port: o.port ? Number(o.port) : void 0, preferPort: DEFAULT_UI_PORT });
    console.log(`gctk UI running at ${ui.url}`);
    console.log("This link contains a session token; do not share it. Stop with Ctrl+C.");
    if (o.open) await openBrowser(target(ui.url));
    const stop = () => ui.close().then(() => process.exit(0));
    process.on("SIGINT", stop);
    process.on("SIGTERM", stop);
    return;
  }
  const url2 = await ensureSharedUi();
  const running = await findRunningUi();
  console.log(`gctk UI is running in the background${running ? ` (pid ${running.info.pid})` : ""}: ${url2}`);
  console.log("This link contains a session token; do not share it. Stop it with the button in the UI or `gctk ui --stop`.");
  if (o.open) await openBrowser(target(url2));
});
program2.command("axl-harness", { hidden: true }).description("internal: Cursor starts this for the ava-harness MCP server (org and credentials from the AXL page)").option("--workshop <id>", "the AXL workshop the folder belongs to").option("--org <profile>", "the workshop's org; must match the AXL page").action(async (o) => {
  try {
    process.exitCode = await runHarness({ workshop: o.workshop, org: o.org });
  } catch (err) {
    process.stderr.write(`gctk: ${formatError(err)}
`);
    process.exitCode = 1;
  }
});
program2.command("demo-source <demo> [profile]", { hidden: true }).description("maintainer: the org this computer takes the demo's snapshot from (kept in the gctk home, never in the package)").option("--replace <value=with...>", "texts of the source org to replace in the snapshot, e.g. a person's name").option("--clear", "remove the snapshot source").action((demo, name, o) => {
  if (o.clear) {
    setSnapshotSource(demo, void 0);
    return console.log(`${demo}: no snapshot source on this computer.`);
  }
  if (name) {
    const replace = (o.replace ?? []).map((r) => {
      const at = r.indexOf("=");
      if (at < 1) throw new GctkError("INVALID_INPUT", `--replace needs value=with, got "${r}".`);
      return { value: r.slice(0, at), with: r.slice(at + 1) };
    });
    setSnapshotSource(demo, { profile: name, ...replace.length ? { replace } : {} });
  }
  const s = snapshotSource(demo);
  if (!s) return console.log(`${demo}: no snapshot source on this computer.`);
  console.log(`${demo}: snapshots come from ${s.profile}`);
  for (const r of s.replace ?? []) console.log(`  replace "${r.value}" with "${r.with}"`);
});
program2.command("project-tool", { hidden: true }).description("internal: Cursor starts this for a Genesys tool of a gctk project folder (org and credentials from the Projects page)").option("--project <id>", "the project the folder belongs to").option("--tool <name>", "the tool, as set up for the project").action(async (o) => {
  try {
    process.exitCode = await runProjectTool(o);
  } catch (err) {
    process.stderr.write(`gctk: ${formatError(err)}
`);
    process.exitCode = 1;
  }
});
program2.command("mcp-launch <id>", { hidden: true }).description("internal: the editor starts this for an MCP server whose secrets the AI setup page moved to the keychain").action(async (id) => {
  try {
    process.exitCode = await runLaunch(id);
  } catch (err) {
    process.stderr.write(`gctk: ${formatError(err)}
`);
    process.exitCode = 1;
  }
});
program2.command("mcp").description("run the MCP server on stdio (used by Cursor / Claude Code to open the UI)").action(() => {
  try {
    if (/gctk\.js$/.test(process.argv[1] ?? "")) ensureStableGctk(process.argv[1]);
  } catch {
  }
  return runMcpServer();
});
program2.parseAsync().catch((err) => {
  console.error(formatError(err));
  process.exit(1);
});
